293	// ---- helpers --------------------------------------------------------------------------------------------------------
294	const inBox = (b, x, y, z) => x >= b[0] && y >= b[1] && z >= b[2] && x <= b[3] && y <= b[4] && z <= b[5];
295	const span = (a, b) => Array.from({ length: Math.abs(b - a) + 1 }, (_, i) => Math.min(a, b) + i);
296	/** The plaster hash (plan.md wallCell): smooth_sandstone 70 / end_stone_bricks 20 / sandstone 10, by position. */
297	const plasterAt = (x, y, z) => {
298	  const h = (x * 7 + z * 13 + y * 5) % 10;
299	  return h < 7 ? SMOOTH_SANDSTONE : h < 9 ? END_STONE_BRICKS : SANDSTONE;
300	};
301	const need = (ok, msg) => { if (!ok) throw new RangeError(msg); };
302	
303	// ---- walls and shell ------------------------------------------------------------------------------------------------
304	/**
305	 * One wall cell at height y (1..6): stone_bricks plinth (y1), red_terracotta dado (y2..3), hashed plaster (y4..5), cut_sandstone
306	 * cornice (y6). kind ext|int is the same finish inside and out (plan E21, E22).
307	 */
308	export function wallCell(g, x, y, z, kind = "int") {
309	  need(kind === "ext" || kind === "int", `wallCell: kind ${kind} (ext|int)`);
310	  need(y >= 1 && y <= 6, `wallCell: y ${y} is outside the wall (1..6)`);
311	  const block = y === 1 ? STONE_BRICKS : y <= 3 ? RED_TERRACOTTA : y <= 5 ? plasterAt(x, y, z) : CUT_SANDSTONE;
312	  g.set(x, y, z, block);
313	}
