315	/** A straight 1-thick wall from (x0,z0) to (x1,z1), y1..6, with wallCell on every cell except those inside an `open` box. */
316	export function wallLine(g, x0, z0, x1, z1, { open = [], kind = "int" } = {}) {
317	  need(x0 === x1 || z0 === z1, "wallLine: a wall runs along x or along z");
318	  for (const x of span(x0, x1)) for (const z of span(z0, z1)) for (let y = 1; y <= 6; y++) {
319	    if (open.some((b) => inBox(b, x, y, z))) continue;
320	    wallCell(g, x, y, z, kind);
321	  }
322	}
