448	/**
449	 * A parterre bed x0..x1 by z0..z1 (3x5): grass_block at y1; a hedge ring at y2 with every 4th ring cell flowering; flowers at
450	 * y2 on the interior cells in z order (flowers[k % n]); the centre cell is left empty for the statue.
451	 */
452	export function gardenBed(g, x0, z0, x1, z1, flowers = [POPPY, AZURE_BLUET]) {
453	  const cx = Math.floor((x0 + x1) / 2), cz = Math.floor((z0 + z1) / 2);
454	  let ring = 0, k = 0;
455	  for (const z of span(z0, z1)) for (const x of span(x0, x1)) {
456	    g.set(x, 1, z, GRASS_BLOCK);
457	    const edge = x === x0 || x === x1 || z === z0 || z === z1;
458	    if (edge) hedge(g, x, z, ring++ % 4 === 3);
459	    else if (!(x === cx && z === cz)) g.set(x, 2, z, flowers[k++ % flowers.length]);
460	  }
461	}
