463	/**
464	 * A fountain basin x0..x1 by z0..z1 (6x5): smooth_quartz rim at y2, blue_terracotta floor at y1, water at y2 on the interior
465	 * except the centre pedestal: quartz_pillar (y2..3) with water_cauldron (level 3) on top at y4 on each of its two cells.
466	 */
467	export function fountain(g, x0, z0, x1, z1) {
468	  const ix0 = x0 + 1, ix1 = x1 - 1, mid = (ix0 + ix1) / 2;
469	  const pedZ = Math.floor((z0 + z1) / 2), pedX = [Math.floor(mid), Math.ceil(mid)];
470	  for (const z of span(z0, z1)) for (const x of span(x0, x1)) {
471	    if (x === x0 || x === x1 || z === z0 || z === z1) { g.set(x, 2, z, SMOOTH_QUARTZ); continue; }
472	    g.set(x, 1, z, BLUE_TERRACOTTA);
473	    if (z === pedZ && pedX.includes(x)) {
474	      g.set(x, 2, z, QUARTZ_PILLAR, { axis: "y" });
475	      g.set(x, 3, z, QUARTZ_PILLAR, { axis: "y" });
476	      g.set(x, 4, z, WATER_CAULDRON, { level: "3" });
477	    } else g.set(x, 2, z, WATER);
478	  }
479	}
