481	/**
482	 * The rain pool: water at y1 over POOL (x15..20, z14..17), and smooth_quartz_slab coping (bottom) at y2 on the ring of
483	 * COMPLUVIUM (x14..21, z13..18) without its four column corners: 20 cells.
484	 */
485	export function impluvium(g) {
486	  for (const x of span(POOL.x0, POOL.x1)) for (const z of span(POOL.z0, POOL.z1)) g.set(x, 1, z, WATER);
487	  const { x0, z0, x1, z1 } = COMPLUVIUM;
488	  for (const x of span(x0, x1)) for (const z of span(z0, z1)) {
489	    const edge = x === x0 || x === x1 || z === z0 || z === z1;
490	    const corner = (x === x0 || x === x1) && (z === z0 || z === z1);
491	    if (edge && !corner) g.set(x, 2, z, ...B.slab("smooth_quartz", "bottom"));
492	  }
493	}
494	
495	// ---- floors ---------------------------------------------------------------------------------------------------------
496	/**
497	 * A floor mosaic at y1 over a ROOMS box (its x and z extents). style is one object or an array, applied in order:
498	 * {kind:"checker", a, b}  (x+z even -> a)
499	 * {kind:"border", field, b1, b2}  (outer ring b1, next ring b2, the rest field)
500	 * {kind:"meander", a, b, field?}  (outer ring alternates pairs of a and b; the inside is field, or left as it is)
501	 * {kind:"emblem", at: [x0,z0,x1,z1], block}  (a block over that rectangle)
502	 */
503	export function mosaic(g, box, style) {
504	  const [x0, , z0, x1, , z1] = box;
505	  for (const s of [style].flat()) {
506	    for (const x of span(x0, x1)) for (const z of span(z0, z1)) {
507	      const depth = Math.min(x - x0, x1 - x, z - z0, z1 - z);
508	      const block = mosaicCell(s, x, z, depth);
509	      if (block) g.set(x, 1, z, block);
510	    }
511	  }
512	}
513	function mosaicCell(s, x, z, depth) {
514	  switch (s.kind) {
515	    case "checker": return (x + z) % 2 === 0 ? s.a : s.b;
516	    case "border": return (depth === 0 ? s.b1 : depth === 1 ? s.b2 : s.field) ?? null;
517	    case "meander": return depth === 0 ? ((x + z) % 4 < 2 ? s.a : s.b) : s.field ?? null;
518	    case "emblem": {
519	      const [ex0, ez0, ex1, ez1] = s.at;
520	      return x >= ex0 && x <= ex1 && z >= ez0 && z <= ez1 ? s.block : null;
521	    }
522	    default: throw new RangeError(`mosaic: unknown style ${s.kind}`);
523	  }
524	}
525	
526	// ---- furniture ------------------------------------------------------------------------------------------------------
527	/**
528	 * A couch: red_bed pieces end to end along a row of len cells (len/2 beds; foot then head, facing along the row), with
529	 * dark_oak_slab rails on the wall side of each cell. facing = the way the couch faces, out from the wall; len must be even.
530	 */
531	export function couch(g, x, z, facing, len) {
532	  need(len % 2 === 0, "couch: len must be even (2 cells per bed)");
533	  need(["north", "south", "east", "west"].includes(facing), `couch: facing ${facing}`);
534	  const along = facing === "north" || facing === "south" ? "east" : "south";
535	  const [dx, , dz] = DIRS[along];
536	  const [bx, , bz] = DIRS[OPPOSITE[facing]];
537	  for (let i = 0; i < len; i++) {
538	    const cx = x + dx * i, cz = z + dz * i;
539	    g.set(cx, 2, cz, RED_BED, { facing: along, part: i % 2 === 0 ? "foot" : "head" });
540	    g.set(cx + bx, 2, cz + bz, ...B.slab("dark_oak", "bottom"));
541	  }
542	}
543	
544	/** A low table: dark_oak_fence legs at the four corners (y2) and a dark_oak_slab top (type top) at y3 over w x d cells. */
545	export function table(g, x, z, w, d) {
546	  for (const cx of span(x, x + w - 1)) for (const cz of span(z, z + d - 1)) g.set(cx, 3, cz, ...B.slab("dark_oak", "top"));
547	  for (const [cx, cz] of [[x, z], [x + w - 1, z], [x, z + d - 1], [x + w - 1, z + d - 1]]) g.set(cx, 2, cz, DARK_OAK_FENCE);
548	}
549	----
550	// Builds the villa from its parts: the ground, then every part in plan order. runParts lets each part only ADD into air
551	// (writes into an earlier part's cells are refused and reported) and reports off-palette blocks per part.
552	// Usage: node build.mjs <out.nbt>
553	import { fileURLToPath } from "node:url";
554	import { Grid, runParts } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
555	import { SITE } from "./vocab.mjs";
