568	import * as room7 from "./parts/room-7.mjs";
569	import * as room8 from "./parts/room-8.mjs";
570	import * as room9 from "./parts/room-9.mjs";
571	import * as room10 from "./parts/room-10.mjs";
572	import * as room11 from "./parts/room-11.mjs";
573	import * as room12 from "./parts/room-12.mjs";
574	import * as room13 from "./parts/room-13.mjs";
575	import * as room14 from "./parts/room-14.mjs";
576	import * as room15 from "./parts/room-15.mjs";
577	import * as room16 from "./parts/room-16.mjs";
578	import * as room17 from "./parts/room-17.mjs";
579	import * as room18 from "./parts/room-18.mjs";
580	
581	const out = process.argv[2];
582	if (!out) {
583	  console.error("usage: node build.mjs <out.nbt>");
584	  process.exit(2);
585	}
586	
587	const g = new Grid(SITE.size, { dataVersion: SITE.dataVersion });
