589	g.fill([0, 0, 0], [SITE.size[0] - 1, 0, SITE.size[2] - 1], "grass_block");
590	
591	runParts(
592	  g,
593	  [
594	    ["P1 shell", shell.build],
595	    ["P2 roofs", roofs.build],
596	    ["P3 street", street.build],
597	    ["P4 atrium", atrium.build],
598	    ["P5 peristyle", peristyle.build],
599	    ["P6 finish", finish.build],
600	    ["room 1 Fauces", room1.build],
601	    ["room 2 Taberna W1", room2.build],
602	    ["room 3 Taberna W2", room3.build],
603	    ["room 4 Taberna E3", room4.build],
604	    ["room 5 Taberna E4", room5.build],
605	    ["room 6 Atrium", room6.build],
606	    ["room 7 Cubiculum C1", room7.build],
607	    ["room 8 Cubiculum C2", room8.build],
608	    ["room 9 Cubiculum C3", room9.build],
609	    ["room 10 Cubiculum C4", room10.build],
